"""Persist the manual derivatives review, source conflicts and numerical checks."""

import json
import math
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]


def write(path, value):
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def bs(s, k, r, sigma, years):
    """Return no-dividend European Black-Scholes values for diagnostic examples."""
    cdf = lambda x: (1 + math.erf(x / math.sqrt(2))) / 2
    d1 = (math.log(s / k) + (r + sigma * sigma / 2) * years) / (sigma * math.sqrt(years))
    d2 = d1 - sigma * math.sqrt(years)
    density = math.exp(-d1 * d1 / 2) / math.sqrt(2 * math.pi)
    discount = math.exp(-r * years)
    call = s * cdf(d1) - k * discount * cdf(d2)
    gamma = density / (s * sigma * math.sqrt(years))
    theta_call = -s * density * sigma / (2 * math.sqrt(years)) - r * k * discount * cdf(d2)
    return dict(call=call, put=call+k*discount-s, delta_call=cdf(d1), delta_put=cdf(d1)-1, gamma=gamma, vega=s*density*math.sqrt(years), theta_call=theta_call, theta_put=theta_call+r*k*discount)


def main():
    outline=json.loads((ROOT/'outline.json').read_text(encoding='utf-8'))
    chapter=next(c for c in outline['chapters'] if c['id']=='S3C6')
    lessons=[
        ("파생상품의 개요","거래대상·장소·기초위험의 독립된 분류축을 설명한다.","주가·금리·환율·상품가격·신용위험 중 어떤 변수를 계약의 지급액에 연결했는지 먼저 본다. 선물과 선도는 미래 거래의 약속이고 옵션은 선택권이다. 장내·장외는 거래구조 분류이므로 기초자산 분류와 섞지 않는다.","대상: 선도·선물/옵션/스왑; 위험: 주·채·통·상·신.","가치가 파생된다는 말을 그 자체의 가치가0이라는 뜻으로 해석; 국내 상품 예시를 전 세계·전 시점으로 확대.","통화선물과 선물환을 기초위험과 거래장소로 각각 분류하라.","계약이 참조하는 변수와 거래방식을 두 칸에 따로 적는다."),
        ("선도거래","계약가격 대비 만기손익과 상대방 이행위험을 분리한다.","배추를3개월 뒤3000원에 사기로 했는데 만기 시세가5000원이면 매수자의 계약상 이익은2000원이다. 매도자의 계약상 손익은−2000원이다. 이는 생산자의 전체 사업이 손실이라는 뜻이 아니다. 상대방이 약속을 이행하지 않을 위험은 이 손익 합계와 별개의 문제다.","선도매수 만기손익=ST−K; 매도=K−ST.","제로섬을 신용위험의 정의로 삼음; 현금결제 선도는NDF만 가능하다는 단정.","만기 시세7000원에서 양측 계약손익은+4000/−4000. 생산·판매 사업손익과 같은가? 아니다.","파생계약 손익과 기존 사업 현금흐름을 별도 표로 만든다."),
        ("선물거래 메커니즘","증거금·일일정산·청산·미결제약정을 단계별로 처리한다.","유지증거금은 추가 납부를 판단하는 문턱이고 개시증거금은 교재 모형의 복구 목표다. 개시1500·유지1000·정산잔액600이면900을 보충한다. 새 매수와 새 매도가 만나면 열린 계약은1개 증가한다. 양쪽이 기존 계약을 닫으면1개 감소한다.","문턱 확인→미달일 때 개시−잔액; 신규/신규+1, 청산/청산−1, 혼합0.","거래량과 미결제약정을 같다고 봄; 유지수준까지만 충전; 선물은 제로섬이 아니라는314쪽 오류.","개시120·유지80·잔액90이면 추가0. 신규→이전→이전→양측청산이면OI0.","증거금 판단과 금액 계산을 분리하고 계약의 두 당사자 상태를 기록."),
        ("선물거래의 기능","위험전가·가격발견·차익거래의 역할을 사례로 구분한다.","달러를 받을 수출자는 달러가격 하락이 걱정이므로 달러선물을 판다. 달러를 지급할 수입자는 반대로 산다. 선물가격에는 보유비용과 수요도 반영되므로 미래 현물가격을 확정적으로 알려주는 숫자는 아니다. 차익거래는 가격 간 불일치를 줄인다.","받을 자산의 하락위험→매도; 살 자산의 상승위험→매수.","파생상품은 항상 부외거래라는 오래된 회계 설명; 낮은 증거금을 무위험·무비용과 혼동.","6개월 뒤 달러를 받을 기업의 헤지 방향과 선물가격이 예측과 다른 이유를 설명.","먼저 기존 계약 때문에 어느 가격 방향에서 손해인지 표시."),
        ("선물의 균형가격","보유비용·통화별 금리·기간을 일치시켜 이론가격과 비교한다.","달러원1200, 원화4%, 달러2%의1년 선도는 연 단리 기준1200×1.04/1.02≈1223.529다. 교재의1224는 금리차 근사다. 시장선도가1230이면 원화를 빌려 달러를 사서 예금하고 만기의1.02달러를 선도로 팔면1248원 상환 후6.6원이 남는다.","FX F=S(1+rdT)/(1+rfT); 주가지수 교재근사F≈S[1+(r−q)T].","정확한 금리비율에서 금리차 근사로 가는 단계를 항등식처럼 처리; 만기 현금흐름의 통화 혼합.","S100,r6%,배당2%,3개월이면 교재근사F101. FX예시 선도매도금액은1달러가 아닌1.02달러인 이유를 설명.","현재와 만기의 원화·외화 수지를 따로 맞춘다."),
        ("선물의 투기와 헤지","방향·손익·계약수·베이시스 잔존위험을 계산한다.","200에10계약 팔고190에 사서 닫으면 계약당10포인트 이익이다. 승수50만원을 가정하면5000만원이다. 주식100억원·베타1.2를1계약1억원 선물로 시장위험 헤지하면120계약 매도다. 최소분산 비율은 상관계수×현물표준편차/선물표준편차이며 이를 계약수로 바꿀 때 단위가 더 필요하다.","매수손익=(종료−시작)×승수×계약수; N≈βV/(F×승수); h*=Cov/Var.","h*=1을 무조건1계약으로 해석; 선물 만기이면 다른 종목의 현물위험까지 사라진다고 단정.","분산25·4와ρ.4면h*=1. 현물금액이 선물1계약의100배라면 수익률 기준 비율에서100계약임을 설명.","금액·수량·수익률 중 분산을 계산한 변수의 단위를 먼저 적는다."),
        ("선물 차익거래","현물가격이 아니라 보유비용을 반영한 이론가격과 비교한다.","현물100, 만기까지 순보유비용2이면 이론선물은102다. 시장선물105를 팔고 현물을100에 사서 보유하면 비용을 제한 순차익은3이다. 선물101은 현물보다 비싸도 이론가102보다 싸다. 따라서 콘탱고라는 이유만으로 현물매수 차익거래를 선택하면 틀린다.","F시장>F이론: 현물매수·선물매도; 반대면 반대 포지션.","325쪽 핵심·364쪽추가5·NOTE14가 베이시스 양수와 차익을 동일시; 합성채권 절세도 조건 누락.","S100,F*102,F101이면 콘탱고지만 매수차익거래 조건이 성립하는가? 아니다.","S,F*,F 세 숫자를 나란히 놓고 실제 괴리 F−F*만 표시."),
        ("스프레드거래","가격차 정의와 매매 부호에서 손익을 도출한다.","스프레드를 원월−근월로 정의한다. 현재 원월95·근월90이고 차이가5에서2로 줄면 원월매도·근월매수 포지션은3포인트를 번다. 반대로 확대 예상은 원월매수·근월매도다. 선물의 강세라는 명칭은 여기서 근월의 상대적 강세를 뜻한다.","원월−근월: 확대는 원월매수, 축소는 원월매도; 수평=만기차, 수직=행사가차.","선물을 시작할 때 가격차 전액을 지불한다고 설명; 선물 강세와 옵션 강세를 동일 의미로 암기.","근월100→105, 원월102→110이면 원월매수·근월매도 손익은8−5=3.","두 계약 손익을 따로 계산해 합한 뒤 스프레드 변화와 대조."),
        ("옵션기초","권리와 의무·프리미엄·행사시점을 구분하고4개 손익곡선을 읽는다.","콜은 정한 가격에 살 권리, 풋은 팔 권리다. 매수자는 프리미엄을 내고 유리할 때 행사한다. 매도자는 프리미엄을 받는 대신 그 행사에 응할 의무를 진다. 손익곡선은 매수자의 값을 구한 뒤 부호를 바꾸면 매도자가 된다.","유럽형 만기만/미국형 만기 포함 이전; 콜max(S−K,0), 풋max(K−S,0).","내가격이면 프리미엄까지 회수한 이익이라고 생각; 콜의 무제한 최대이익을 무제한 기대수익이라고 표현.","콜K100·프리미엄3·만기S101이면 행사가치1이나 순손익−2임을 설명.","행사대금과 처음 지출한 프리미엄을 별도로 기록."),
        ("옵션 내재가치와 가격","내재·시간가치·프리미엄·손익분기점을 구분해 계산한다.","S103,K100인 콜의 내재가치는3이다. 시장가격이3.5이면 차이.5가 시간가치다. S70,K80이면 콜 내재가치는0이다. 살 필요가 없을 때 권리를 쓰지 않기 때문에−10으로 내려가지 않는다. 만기 콜 손익분기점은K+프리미엄이다.","프리미엄=내재가치+시간가치; 콜BEP=K+C, 풋BEP=K−P(비용·이자 생략).","C=S−K라는335쪽 설명을 옵션가격 공식으로 암기; 유럽형 풋도 항상 양의 시간가치라고 확대.","S400,K395,C8이면내재5·시간3. S253,K250,P1이면풋내재0·시간1.","max의 두 후보를 먼저 비교하고 그 다음 프리미엄에서 뺀다."),
        ("옵션 방향성 합성전략","낮은·높은 행사가 옵션의 손익을 합쳐 방향과 손익한도를 구한다.","낮은K 콜을 사고 높은K 콜을 팔면 상승에 참여하되 높은K 위의 이익은 포기한다. 받은 프리미엄으로 비용을 줄인 구조다. 풋K295를1.5에 사고 풋K300을5에 팔았다면 초기+3.5, 만기S295의 행사정산−5, 순손익−1.5다.","강세콜=낮은K매수·높은K매도; 강세풋도 같은 매수/매도 방향. 콜 순지출·풋 순수취.","스프레드의 theta가 항상0이라는338쪽 주장; 만기손익과 현재 델타를 혼동.","K100콜3매수·K105콜2매도, 만기105이면−1+5=4; 최대손실1·최대이익4.","각 leg의 프리미엄과 만기정산을2×2표에 쓰고 합산."),
        ("옵션 변동성 전략","스트래들·스트랭글의 구성과 손익구간을 계산한다.","같은K의 콜과 풋을 사면 어느 쪽으로든 충분히 크게 움직일 때 이익이다. 모두 팔면 작은 움직임이 유리하다. K100의 콜5·풋3을 함께 팔면 초기8을 받고 만기손익은8−|S−100|이므로92<S<108에서 이익이다. 스트랭글은 낮은K 풋과 높은K 콜을 사용한다.","스트래들 같은K/스트랭글 다른K; 롱은 큰 이동, 숏은 제한된 이동.","스트랭글매도를 변동성매수라고 한337쪽; 풋매수는 vega가 없다는345쪽 오답 해설.","K80에프리미엄합5의 숏스트래들 수익구간은75<S<85; 경계는 이익0.","하락·중간·상승 구간으로 나누어 콜과 풋 중 무엇이 행사되는지 확인."),
        ("풋콜패리티","같은 만기지급을 복제하는 두 포트폴리오의 현재가치를 맞춘다.","주식+풋은 만기에 주가와K 중 큰 값을 받는다. 만기에K를 주는 채권+콜도 같은 값을 받는다. 따라서 무배당 유럽형의 같은K·만기 옵션에서는C+PV(K)=P+S다. S와K가 같을 필요는 없다.","C+B=P+S; C=P+S−B; P=C+B−S.","ATM을 필수 전제로 잘못 제시; 배당과 차입·대차비용·미국형 조기행사 조건 생략.","S200,K200,C4,r4%,3개월 단리할인이면P=4+200/1.01−200≈2.0198.","만기S<K와S>K의 두 줄에서 양쪽 지급액이 같은지 먼저 검증."),
        ("컨버전과 리버설","패리티의 비싼 묶음을 팔고 싼 묶음을 산다.","C+B가P+S보다 비싸면 콜매도·채권발행으로 자금을 마련해 풋과 주식을 산다. 양쪽 만기지급이 같으므로 현재가격 차이를 확보하는 컨버전이다. 반대 부등호이면 모든 포지션을 뒤집은 리버설이다.","컨버전=−C−B+P+S; 리버설=+C+B−P−S.","현물 매수/매도와 합성선물 매수/매도를 섞어 이름으로만 암기.","C+B<P+S일 때 주식매도·풋매도·콜매수·채권매수가 되는 이유를 설명.","괄호 두 묶음에 매수+·매도−를 붙인 뒤 전개."),
        ("포트폴리오보험","보호적풋·채권+콜·동적복제의 지급과 비용을 비교한다.","주식과풋을 보유하면 약정K 아래의 만기가치를 막는다. 같은 지급은K를 만들 채권과콜로 구성할 수 있다. 주식100%에 선물60%를 매도한 노출은 단순화하면 주식40%+합성채권60%다. 동적 조정은 거래비용과 가격점프 때문에 완전 복제를 보장하지 않는다.","보호적풋=S+P; 이자추출=B+C; 델타는 주식 수량이며 자산비중은ΔS/V.","CB·ELS라면 항상 원금보장으로 해석; S+P=C라고 채권을 빠뜨림; 델타를 비중으로 직접 사용.","주식100·선물매도60의 순주식노출40을 설명하고 floor와 초기 원금의 차이를 구분.","만기지급과 초기 구성비용을 따로 계산하고 복제 가정을 적는다."),
        ("이항모형","무차익 복제와 위험중립 확률 두 방식으로 같은 가격을 계산한다.","S1000이1400 또는600이 되고K1000콜이400 또는0이면 주식.5주−콜의 만기가치는 항상300이다. r10%면 현재500−C=300/1.1이므로C227.2727이다. 위험중립확률은(1100−600)/(1400−600)=.625이고400×.625/1.1도 같다.","p=(S0(1+r)−Sd)/(Su−Sd); Δ=(Cu−Cd)/(Su−Sd); C=[pCu+(1−p)Cd]/(1+r).","실제 상승확률과 위험중립확률 혼동; 제시값 충돌을 무조건 문제 우선이라고 채점; 행사가 생략.","S100→120/80,r10%,K100이면p.75,C13.6364. p가0~1밖이면 가정과 무차익조건 점검.","주식가격식과 옵션가격식에 동일한p를 넣어 두 식이 동시에 성립하는지 확인."),
        ("블랙숄즈모형","입력변수·델타·위험중립 행사확률의 역할을 구분한다.","무배당 유럽형 콜은S·N(d1)−PV(K)·N(d2)로 표현한다. N(d1)은 주가에 대한 콜의 델타, N(d2)는 모형의 위험중립 측도에서 만기내가격 확률이다. 동일조건 풋의 델타는N(d1)−1이므로 콜델타.7이면풋델타−.3이다.","S,K,r,σ,잔존기간; Δput=Δcall−1(무배당).","풋델타에 마이너스 누락; N(d2)를 실제 미래 확률로 해석; 연 복리r와 연속복리r를 같은 수치로 섞음.","콜델타.6→풋델타−.4. 기초자산의 기대수익률μ가 가격공식의 직접 입력이 아닌 이유를 무차익복제로 설명.","가격·수량민감도·확률을 각각 다른 칸에 적는다."),
        ("기초자산의 변동성","과거 실현변동성과 시장가격에서 역산한 내재변동성을 구분한다.","이미 관측한 가격으로 계산한 값은 과거변동성이다. 옵션가격을 모형에 맞춰 역산한σ는 내재변동성이다. 미래 실제 변동성이 그 숫자로 확정되는 것은 아니다. 스마일·스큐는 행사가별 역산값의 모양이며 축이K/S인지S/K인지 먼저 읽어야 한다.","과거자료→실현변동성; 시장옵션가격→내재변동성.","356쪽 콜 기준 K/S 증가에 IV 증가를 주가지수의 전형적 하방스큐라고 설명; 미래실현값과 내재값 동일시.","낮은 행사가의 OTM풋에 높은IV가 붙는 경우 K/S축의 기울기는 어느 방향인가? 대체로 하향.","같은K·만기의 콜/풋을 연결하고 낮은K와 높은K의 위치부터 표시."),
        ("옵션 민감도","변수 한 개 변화의 효과와 포지션별 합산을 계산한다.","델타는 주가 변화에 대한 옵션가격 변화, 감마는 주가 변화에 대한 델타 변화다. 베가는σ, 세타는 시간 경과, 로는 금리 변화에 대한 민감도다. 콜델타.6인2개와 풋델타−.4인1개의 합은.8이다. 매도수량은 부호를 뒤집는다.","Δ:V의S미분, Γ:Δ의S미분, Vega:σ, Theta:시간, Rho:r.","ATM델타=.5와 감마최대가 항상 정확하다고 단정; 모든 풋theta음수; Γ+Θ=상수라는361쪽 오류.","콜1개 델타.5를 매도했다면 주식.5주로 1차중립. 주식1주에는 콜2개 매도. 그래도 감마위험은 남음을 설명.","원하는 변수만 움직이는 작은 변화표를 만들고 각 계약 수량×민감도를 합산."),
    ]
